import{_ as o,a0 as p,w as r,s as u,ao as l,I as n,x as t,a1 as s,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const V=JSON.parse('{"title":"在 Linux 上安装使用 VirtualBox 的命令行管理界面 VBoxManage | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安装使用 VirtualBox 的命令行管理界面 VBoxManage | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安装使用 VirtualBox 的命令行管理界面 VBoxManage | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安装使用 VirtualBox 的命令行管理界面 VBoxManage | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160603 How To Install And Use VBoxManage On Ubuntu 16.04 And Use Its Command line Options","title":"在 Linux 上安装使用 VirtualBox 的命令行管理界面 VBoxManage","tag":"201607","desc":""},"relativePath":"201607/20160603 How To Install And Use VBoxManage On Ubuntu 16.04 And Use Its Command line Options.md","filePath":"[post].md"}'),d={name:"201607/20160603 How To Install And Use VBoxManage On Ubuntu 16.04 And Use Its Command line Options.md"};function g(h,a,b,c,k,x){const i=p("Link");return r(),u("div",null,[a[16]||(a[16]=l('<h1 id="在-linux-上安装使用-virtualbox-的命令行管理界面-vboxmanage" tabindex="-1">在 Linux 上安装使用 VirtualBox 的命令行管理界面 VBoxManage <a class="header-anchor" href="#在-linux-上安装使用-virtualbox-的命令行管理界面-vboxmanage" aria-label="Permalink to “在 Linux 上安装使用 VirtualBox 的命令行管理界面 VBoxManage”">​</a></h1><p>VirtualBox 拥有一套命令行工具，你可以使用 VirtualBox 的命令行界面 (CLI) 对远程无界面的服务器上的虚拟机进行管理操作。在这篇教程中，你将会学到如何在没有 GUI 的情况下使用 VBoxManage 创建、启动一个虚拟机。VBoxManage 是 VirtualBox 的命令行界面，你可以在你的主机操作系统的命令行中用它来实现对 VirtualBox 的所有操作。VBoxManage 拥有图形化用户界面所支持的全部功能，而且它支持的功能远不止这些。它提供虚拟引擎的所有功能，甚至包含 GUI 还不能实现的那些功能。如果你想尝试下不同的用户界面而不仅仅是 GUI，或者更改虚拟机更多高级和实验性的配置，那么你就需要用到命令行。</p><p>当你想要在 VirtualBox 上创建或运行虚拟机时，你会发现 VBoxManage 非常有用，你只需要使用远程主机的终端就够了。这对于需要远程管理虚拟机的服务器来说是一种常见的情形。</p><h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to “准备工作”">​</a></h3><p>在开始使用 VBoxManage 的命令行工具前，确保在运行着 Ubuntu 16.04 的服务器上，你拥有超级用户的权限或者你能够使用 sudo 命令，而且你已经在服务器上安装了 Oracle Virtual Box。 然后你需要安装 VirtualBox 扩展包，这是运行 VRDE 远程桌面环境，访问无界面虚拟机所必须的。</p><h3 id="安装-vboxmanage" tabindex="-1">安装 VBoxManage <a class="header-anchor" href="#安装-vboxmanage" aria-label="Permalink to “安装 VBoxManage”">​</a></h3>',6)),n("p",null,[a[1]||(a[1]=t("通过 ",-1)),s(i,{href:"https://www.virtualbox.org/wiki/Downloads"},{default:e(()=>[...a[0]||(a[0]=[t("Virtual Box 下载页",-1)])]),_:1}),a[2]||(a[2]=t(" 这个链接，你能够获取你所需要的软件扩展包的最新版本，扩展包的版本和你安装的 VirtualBox 版本需要一致！",-1))]),a[17]||(a[17]=l(`<p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/12.png" alt=""></p><p>也可以用下面这条命令来获取 VBoxManage 扩展。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://download.virtualbox.org/virtualbox/5.0.20/Oracle_VM_VirtualBox_Extension_Pack-5.0.20-106931.vbox-extpack</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/21.png" alt=""></p><p>运行下面这条命令，确认 VBoxManage 已经成功安装在你的机器上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage list extpacks</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/31.png" alt=""></p><h3 id="在-ubuntu-16-04-上使用-vboxmanage" tabindex="-1">在 Ubuntu 16.04 上使用 VBoxManage <a class="header-anchor" href="#在-ubuntu-16-04-上使用-vboxmanage" aria-label="Permalink to “在 Ubuntu 16.04 上使用 VBoxManage”">​</a></h3><p>接下来我们将要使用 VBoxManage 向你展现通过命令行终端工具来新建和管理虚拟机是多么的简单。</p><p>运行下面的命令，新建一个将用来安装 Ubuntu 系统的虚拟机。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># VBoxManage createvm --name Ubuntu16.04 --register</span></span></code></pre></div><p>在运行了这条命令之后，VBoxMnage 将会新建一个叫 做“Ubuntu16.vbox” 的虚拟机，这个虚拟机的位置是家目录路径下的 “VirtualBox VMs/Ubuntu16/Ubuntu16.04.vbox”。在上面这条命令中，“createvm” 是用来新建虚拟机，“--name” 定义了虚拟机的名字，而 “registervm” 命令是用来注册虚拟机的。</p><p>现在，使用下面这条命令为虚拟机创建一个硬盘镜像。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage createhd --filename Ubuntu16.04 --size 5124</span></span></code></pre></div><p>这里，“createhd” 用来创建硬盘镜像，“--filename” 用来指定虚拟机的名称，也就是创建的硬盘镜像名称。“--size” 表示硬盘镜像的空间容量，空间容量的单位总是 MB。我们指定了 5Gb，也就是 5124 MB。</p><p>接下来我们需要设置操作系统类型，如果要安装 Linux 系的系统，那么用下面这条命令指定系统类型为 Linux 或者 Ubuntu 或者 Fedora 之类的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage modifyvm Ubuntu16.04 --ostype Ubuntu</span></span></code></pre></div><p>用下面这条命令来设置虚拟系统的内存大小，也就是从主机中分配到虚拟机系统的内存。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage modifyvm Ubuntu10.10 --memory 512</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/52.png" alt=""></p><p>现在用下面这个命令为虚拟机创建一个存储控制器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage storagectl Ubuntu16.04 --name IDE --add ide --controller PIIX4 --bootable on</span></span></code></pre></div><p>这里的 “storagect1” 是给虚拟机创建存储控制器的，“--name” 指定了虚拟机里需要创建、更改或者移除的存储控制器的名称。“--add” 选项指明存储控制器所需要连接到的系统总线类型，可选的选项有 ide / sata / scsi / floppy。“--controller” 选择主板的类型，主板需要根据需要的存储控制器选择，可选的选项有 LsiLogic / LSILogicSAS / BusLogic / IntelAhci / PIIX3 / PIIX4 / ICH6 / I82078。最后的 “--bootable” 表示控制器是否可以引导系统。</p><p>上面的命令创建了叫做 IDE 的存储控制器。之后虚拟介质就能通过 “storageattach” 命令连接到该控制器。</p><p>然后运行下面这个命令来创建一个叫做 SATA 的存储控制器，它将会连接到之后的硬盘镜像上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage storagectl Ubuntu16.04 --name SATA --add sata --controller IntelAhci --bootable on</span></span></code></pre></div><p>将之前创建的硬盘镜像和 CD/DVD 驱动器加载到 IDE 控制器。将 Ubuntu 的安装光盘插到 CD/DVD 驱动器上。然后用 “storageattach” 命令连接存储控制器和虚拟机。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage storageattach Ubuntu16.04 --storagectl SATA --port 0 --device 0 --type hdd --medium &quot;your_iso_filepath&quot;</span></span></code></pre></div><p>这将把 SATA 存储控制器及介质（比如之前创建的虚拟磁盘镜像）连接到 Ubuntu16.04 虚拟机中。</p><p>运行下面的命令添加像网络连接，音频之类的功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage modifyvm Ubuntu10.10 --nic1 nat --nictype1 82540EM --cableconnected1 on</span></span>
<span class="line"><span>$ VBoxManage modifyvm Ubuntu10.10 --vram 128 --accelerate3d on --audio alsa --audiocontroller ac97</span></span></code></pre></div><p>通过指定你想要启动虚拟机的名称，用下面这个命令启动虚拟机。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ VBoxManage startvm Ubuntu16.04</span></span></code></pre></div><p>然后会打开一个新窗口，新窗口里虚拟机通过关联文件中引导。</p><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/62.png" alt=""></p><p>你可以用接下来的命令来关掉虚拟机。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ VBoxManage controlvm Ubuntu16.04 poweroff</span></span></code></pre></div><p>“controlvm” 命令用来控制虚拟机的状态，可选的选项有 pause / resume / reset / poweroff / savestate / acpipowerbutton / acpisleepbutton。controlvm 有很多选项，用下面这个命令来查看它支持的所有选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$VBoxManage controlvm</span></span></code></pre></div><p><img src="http://linuxpitstop.com/wp-content/uploads/2016/06/81.png" alt=""></p><p>###完结</p><p>从这篇文章中，我们了解了 Oracle Virtual Box 中一个十分实用的工具 VBoxManage，文章包含了 VBoxManage 的安装和在 Ubuntu 16.04 系统上的使用，包括通过 VBoxManage 中实用的命令来创建和管理虚拟机。希望这篇文章对你有帮助，另外别忘了分享你的评论或者建议。</p><hr>`,43)),n("p",null,[a[4]||(a[4]=t("via: ",-1)),s(i,{href:"http://linuxpitstop.com/install-and-use-command-line-tool-vboxmanage-on-ubuntu-16-04/"},{default:e(()=>[...a[3]||(a[3]=[t("http://linuxpitstop.com/install-and-use-command-line-tool-vboxmanage-on-ubuntu-16-04/",-1)])]),_:1})]),n("p",null,[a[8]||(a[8]=t("作者：",-1)),s(i,{href:"http://linuxpitstop.com/author/kashif/"},{default:e(()=>[...a[5]||(a[5]=[t("Kashif",-1)])]),_:1}),a[9]||(a[9]=t(" 译者：",-1)),s(i,{href:"https://github.com/GitFuture"},{default:e(()=>[...a[6]||(a[6]=[t("GitFuture",-1)])]),_:1}),a[10]||(a[10]=t(" 校对：",-1)),s(i,{href:"https://github.com/wxy"},{default:e(()=>[...a[7]||(a[7]=[t("wxy",-1)])]),_:1})]),n("p",null,[a[13]||(a[13]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[11]||(a[11]=[t("LCTT",-1)])]),_:1}),a[14]||(a[14]=t(" 原创编译，",-1)),s(i,{href:"https://linux.cn/"},{default:e(()=>[...a[12]||(a[12]=[t("Linux中国",-1)])]),_:1}),a[15]||(a[15]=t(" 荣誉推出",-1))])])}const B=o(d,[["render",g]]);export{V as __pageData,B as default};
